presetParts.perFrame:
dec_med = exp (-3/fps);
dec_slow = exp (-.6/fps);

beat = bass+mid+treb;
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .2+avg+peak) * above (time, t0+.1);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %16;
index2 = (index2 + is_beat*bnot(index))%12;

spb = min(t0-t0a + .01,2); t0a = t0;
spb_ = if(is_beat,spb_ *.9 +.1*spb, spb_);
mindev = min(min(abs(spb-spb_),abs(spb*2-spb_)),abs(spb-spb_*2));
sdev = if(is_beat,sdev * .9 + .1*pow(mindev+.02,2),sdev);

q20 = avg; q21 = beat;
q22 = peak+.1; 
q24 = is_beat;
q27 = index; q28 = index2;

trel = trel + 1/fps/spb_*4; itrel = int(trel);
q25 =  above(itrel, itrel_);
q30 = itrel%2;
itrel_ = itrel;
q31 = itrel;

ma = ma + peak/fps ;
mx=mx*dec_med+(1-dec_med)*cos(ma);
my=my*dec_med+(1-dec_med)*sin(ma+trel/16);
q15 = mx ; q16 = my ; q17 = ma;

//first par: off; second: on
sw1 = if(sw1,bnot(q24*bnot(rand(20))),q24*bnot(rand(20)));
sw2 = if(sw2,bnot(q24*bnot(rand(10))),q24*bnot(rand(80)));
sw3 = if(sw3,bnot(q24*bnot(rand(10))),q24*bnot(rand(100+10000*sdev)));

//********* variation parameters warp shader
q6 = sin(time/15)*sin(time/27)*.2; //zz weighting
q10 = sin(time/8); //ring
q10 = q10*q10*.1; 
